    @Test
    fun matchesTheTrainingSide() {
        for ((i, c) in cases.withIndex()) {
            val (features, points) = InkFeatures.of(c.strokes)!!
            assertEquals("case $i points", c.points, points)
            assertEquals("case $i size", c.expected.size, features.size)
            for (k in features.indices) assertEquals("case $i value $k", c.expected[k], features[k], 1e-5f)
        }
    }

    @Test
    fun noInkIsNull() {
        assertEquals(null, InkFeatures.of(emptyList()))
    }
